#!/usr/bin/env bash
#
# Install ScienceWorld: the simulator package in its own venv plus the Java runtime its
# bundled JAR needs. There is no dataset — tasks are generated by the simulator.
#
# Target layout (see src/wikitrace/envs/textgame/):
#   $DATA_ROOT/scienceworld/.venv/bin/python    # scienceworld 1.3.0 (+ py4j), CPython 3.11
#   $DATA_ROOT/scienceworld/jdk/bin/java        # Temurin 21 JRE
#   $DATA_ROOT/scienceworld/env.sh              # exports JAVA_HOME and PATH for the JRE
#
# Usage:
#   scripts/setup/scienceworld.sh
#   DATA_ROOT=/mnt/data scripts/setup/scienceworld.sh
#
# Sources: the official GitHub repo at the commit the probe pinned (1.3.0 is not on PyPI;
# the JAR ships inside the package), and the Adoptium Temurin 21 JRE tarball (52 MB).
# Java >= 15 is required: the 1.3.0 JAR's goal-progress path uses String.formatted, and
# py4j launches whatever `java` is first on PATH, so a run sources env.sh first.

SCRIPT_DIR="$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)"
. "$SCRIPT_DIR/_lib.sh"

BENCH="scienceworld"
DEST="$DATA_ROOT/$BENCH"
CACHE="$CACHE_ROOT/$BENCH"
VENV="$DEST/.venv"
JDK="$DEST/jdk"

SCIENCEWORLD_REPO_URL="${SCIENCEWORLD_REPO_URL:-https://github.com/allenai/ScienceWorld.git}"
SCIENCEWORLD_COMMIT="${SCIENCEWORLD_COMMIT:-e8216d6044e8e39be9fcb185e3b2dfb602584b52}"
PYTHON_VERSION="${PYTHON_VERSION:-3.11}"
JRE_URL="${JRE_URL:-https://github.com/adoptium/temurin21-binaries/releases/download/jdk-21.0.12%2B8/OpenJDK21U-jre_x64_linux_hotspot_21.0.12_8.tar.gz}"
JRE_SHA256="${JRE_SHA256:-8a379a67c91a3ae61ffb33d46e0a40c7ba35e70713c4db31cfca30492f792eff}"

# uv's default cache lives under $HOME, which is quota-limited on the lab hosts.
export UV_CACHE_DIR="${UV_CACHE_DIR:-$CACHE_ROOT/uv}" UV_LINK_MODE="${UV_LINK_MODE:-copy}"

need uv
mkdir -p "$DEST" "$CACHE"

# pyyaml is for the parity runner (scripts/experiments/reference), which reads a suite yaml.
if "$VENV/bin/python" -c "import scienceworld, py4j, yaml" 2>/dev/null; then
  log "venv already installed at $VENV — skipping"
else
  log "venv: $VENV (python $PYTHON_VERSION)"
  uv venv -q --clear --python "$PYTHON_VERSION" "$VENV"
  uv pip install -q --python "$VENV/bin/python" "git+$SCIENCEWORLD_REPO_URL@$SCIENCEWORLD_COMMIT" pyyaml
fi
assert_file "$VENV/lib/python$PYTHON_VERSION/site-packages/scienceworld/scienceworld.jar"

if [ -x "$JDK/bin/java" ]; then
  log "JRE already installed at $JDK — skipping"
else
  tarball="$CACHE/$(basename "$JRE_URL")"
  fetch "$JRE_URL" "$tarball"
  verify_sha256 "$tarball" "$JRE_SHA256"
  rm -rf "$JDK" "$CACHE/jre-extract"
  extract "$tarball" "$CACHE/jre-extract"
  # The tarball holds one top-level directory (jdk-21.0.12+8-jre); flatten it to jdk/.
  mv "$CACHE/jre-extract"/* "$JDK"
  rmdir "$CACHE/jre-extract"
fi
assert_file "$JDK/bin/java"
"$JDK/bin/java" -version 2>&1 | head -1 >&2

cat > "$DEST/env.sh" <<'EOF'
# Source before running the ScienceWorld simulator: py4j takes `java` from PATH.
export JAVA_HOME="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/jdk"
export PATH="$JAVA_HOME/bin:$PATH"
EOF

cat >&2 <<EOF

[install] ScienceWorld ready under: $DEST
[install] Point the config at it (default already matches):
             dataset:
               scienceworld_root: $DEST
[install] Every process that starts the simulator must have the JRE first on PATH:
             . $DEST/env.sh      # JAVA_HOME=$JDK, PATH=\$JAVA_HOME/bin:\$PATH
          The environment server runs under $VENV/bin/python.
[install] Suite id: scienceworld.
EOF
